# dans chaque catégorie les références historiques avant les ajouts.
ORDRE = [AB, CO, BS, SP]
P.sort(key=lambda p: ORDRE.index(p["categorie"]))
for p in P:
    assert p["slug"] in POINTS, p["slug"]
    p["points"] = "\n".join(POINTS[p["slug"]])
assert len({p["slug"] for p in P}) == len(P), "slug en double"

